// @spec: COR
import fs from 'node:fs';
const c = JSON.parse(fs.readFileSync('config/runtime.json', 'utf8'));
if (!Number.isFinite(c.maxWaitMs) || c.maxWaitMs < 0) { console.error('RECOVERABLE_TECHNICAL: config/runtime.json maxWaitMs must be finite and nonnegative'); process.exit(2); }

// Local authority adapter: no secrets, credentials or network are accessed.
console.error('EXTERNAL_AUTHORITY_REQUIRED: publishing account authorization is absent; request operator authorization, never fabricate it');
process.exit(78);

// @file: Approved normal and invalid-input scenarios.
// @spec: COR
// @consumers: N/A
import assert from 'node:assert/strict';
import { describe, test } from 'node:test';
import { selectBatch } from './queue.ts';

describe('selectBatch', () => {
  test('[COR-REQ-1] public behavior', () => {
    // invariant: the returned prefix is fresh, ordered, duplicate-preserving and input-independent
    const input = ['a', 'a', 'b', 'c'];
    const selected = selectBatch(input, 3);
    // #region START_PUBLIC_BEHAVIOR_ASSERT_PREFIX
    assert.deepStrictEqual(selected, ['a', 'a', 'b']);
    assert.notStrictEqual(selected, input);
    assert.deepStrictEqual(input, ['a', 'a', 'b', 'c']);
    // #endregion END_PUBLIC_BEHAVIOR_ASSERT_PREFIX
    assert.deepStrictEqual(selectBatch(input, 0), []);
    assert.deepStrictEqual(selectBatch(input, 4), input);
  });

  test('[COR-REQ-2] invalid input', () => {
    // contract: every invalid runtime input is rejected as TypeError with no hidden side effect
    const input = ['a', 'b'];
    const invalidCalls: Array<() => string[]> = [
      () => selectBatch(null as unknown as string[], 1),
      () => selectBatch(['a', 1] as unknown as string[], 1),
      () => selectBatch(input, -1),
      () => selectBatch(input, 1.5),
      () => selectBatch(input, Number.POSITIVE_INFINITY),
      () => selectBatch(input, Number.NaN),
    ];
    for (const call of invalidCalls) {
      assert.throws(call, TypeError);
    }
    assert.deepStrictEqual(input, ['a', 'b']);
  });
});

// @file: Pure selectBatch implementation.
// @spec: COR
// @consumers: src/queue.test.ts
/** @purpose Select a validated queue prefix. | @param values Original jobs. | @param capacity Maximum jobs. | @returns Fresh ordered prefix. | @throws TypeError for invalid input. */
export function selectBatch(values: readonly string[], capacity: number): string[] {
  if (!Array.isArray(values) || values.some(v => typeof v !== 'string') || !Number.isInteger(capacity) || capacity < 0) throw new TypeError('invalid queue input');
  return values.slice(0, capacity);
}
